28	func setRoyaltyReq(rid string, shares ...RoyaltyShare) SetRoyaltyRequest {
29		return SetRoyaltyRequest{
30			Operator: "alice", Reason: "设定版税", RequestID: rid,
31			SeriesID: "s1", Shares: shares,
32		}
33	}
