42	// ---- 规则设置与查询 ----
43	
44	func TestSetAndQueryRoyalty(t *testing.T) {
45		r := mustCreate(t, tempDir(t))
46		royaltyWorld(t, r)
47	
48		res, err := r.SetRoyalty(setRoyaltyReq("rs1",
49			RoyaltyShare{AccountID: "carol", Rate: 2500},
50			RoyaltyShare{AccountID: "bob", Rate: 1000},
51		))
52		if err != nil {
53			t.Fatalf("SetRoyalty: %v", err)
54		}
55		if res.Replayed || len(res.Shares) != 2 {
56			t.Fatalf("unexpected set result: %+v", res)
57		}
58		// 规则按收款账户排序规范化
59		rule, err := r.GetSeriesRoyalty("s1")
60		if err != nil {
61			t.Fatal(err)
62		}
63		if len(rule) != 2 || rule[0].AccountID != "bob" || rule[0].Rate != 1000 ||
64			rule[1].AccountID != "carol" || rule[1].Rate != 2500 {
65			t.Fatalf("rule wrong: %+v", rule)
66		}
67		// 变更记录包含操作者、原因、请求号与前后内容
68		evs, err := r.RoyaltyHistory("s1")
69		if err != nil || len(evs) != 1 {
70			t.Fatalf("royalty history: %v %v", evs, err)
71		}
72		if e := evs[0]; e.Operator != "alice" || e.Reason != "设定版税" ||
73			e.RequestID != "rs1" || len(e.Before) != 0 || len(e.After) != 2 {
74			t.Fatalf("royalty event wrong: %+v", e)
75		}
76		// 再次设置（改为只给 dave），前后内容都记录
77		mustSetRoyalty(t, r, "rs2", RoyaltyShare{AccountID: "dave", Rate: 500})
78		evs, _ = r.RoyaltyHistory("s1")
79		if len(evs) != 2 || len(evs[1].Before) != 2 ||
80			len(evs[1].After) != 1 || evs[1].After[0].AccountID != "dave" {
81			t.Fatalf("second event wrong: %+v", evs)
82		}
83		// 清空规则：空份额表示不收版税
84		mustSetRoyalty(t, r, "rs3")
85		rule, _ = r.GetSeriesRoyalty("s1")
86		if len(rule) != 0 {
87			t.Fatalf("cleared rule should be empty: %+v", rule)
88		}
89		evs, _ = r.RoyaltyHistory("s1")
90		if len(evs) != 3 || len(evs[2].After) != 0 || len(evs[2].Before) != 1 {
91			t.Fatalf("clear event wrong: %+v", evs[2])
92		}
93	}
