95	func TestSetRoyaltyValidation(t *testing.T) {
96		r := mustCreate(t, tempDir(t))
97		royaltyWorld(t, r)
98	
99		cases := []struct {
100			name   string
101			shares []RoyaltyShare
102		}{
103			{"重复账户", []RoyaltyShare{{AccountID: "bob", Rate: 1}, {AccountID: "bob", Rate: 2}}},
104			{"比例为零", []RoyaltyShare{{AccountID: "bob", Rate: 0}}},
105			{"比例超上限", []RoyaltyShare{{AccountID: "bob", Rate: 10001}}},
106			{"比例为负", []RoyaltyShare{{AccountID: "bob", Rate: -5}}},
107			{"合计超限", []RoyaltyShare{{AccountID: "bob", Rate: 6000}, {AccountID: "carol", Rate: 4001}}},
108			{"空账户", []RoyaltyShare{{AccountID: " ", Rate: 1}}},
109		}
110		for i, tc := range cases {
111			rid := fmt.Sprintf("bad-%d", i)
112			if _, err := r.SetRoyalty(setRoyaltyReq(rid, tc.shares...)); !errors.Is(err, ErrInvalidArgument) {
113				t.Fatalf("%s: want ErrInvalidArgument, got %v", tc.name, err)
114			}
115			// 参数错误不占用请求号：同一请求号修正参数后可用
116			if _, err := r.SetRoyalty(setRoyaltyReq(rid, RoyaltyShare{AccountID: "dave", Rate: 10})); err != nil {
117				t.Fatalf("%s: request id should not be consumed: %v", tc.name, err)
118			}
119		}
120		// 参数不合法时原规则不变
121		r2 := mustCreate(t, filepath.Join(t.TempDir(), "d2"))
122		royaltyWorld(t, r2)
123		mustSetRoyalty(t, r2, "keep", RoyaltyShare{AccountID: "bob", Rate: 777})
124		if _, err := r2.SetRoyalty(setRoyaltyReq("bad",
125			RoyaltyShare{AccountID: "bob", Rate: 1}, RoyaltyShare{AccountID: "bob", Rate: 2})); !errors.Is(err, ErrInvalidArgument) {
126			t.Fatalf("want ErrInvalidArgument, got %v", err)
127		}
128		rule, _ := r2.GetSeriesRoyalty("s1")
129		if len(rule) != 1 || rule[0].Rate != 777 {
130			t.Fatalf("invalid set must keep original rule: %+v", rule)
131		}
132	}
133	
134	func TestSetRoyaltyPermissionAndState(t *testing.T) {
135		r := mustCreate(t, tempDir(t))
136		royaltyWorld(t, r)
137	
138		// 其他账户操作明确拒绝
139		req := setRoyaltyReq("x1", RoyaltyShare{AccountID: "bob", Rate: 1})
140		req.Operator = "bob"
141		if _, err := r.SetRoyalty(req); !errors.Is(err, ErrForbidden) {
142			t.Fatalf("non-creator must be forbidden, got %v", err)
143		}
144		// 操作者不存在 -> ErrNotFound
145		req = setRoyaltyReq("x2", RoyaltyShare{AccountID: "bob", Rate: 1})
146		req.Operator = "ghost"
147		if _, err := r.SetRoyalty(req); !errors.Is(err, ErrNotFound) {
148			t.Fatalf("unknown operator: %v", err)
149		}
150		// 系列不存在 -> ErrNotFound
151		req = setRoyaltyReq("x3", RoyaltyShare{AccountID: "bob", Rate: 1})
152		req.SeriesID = "nope"
153		if _, err := r.SetRoyalty(req); !errors.Is(err, ErrNotFound) {
154			t.Fatalf("unknown series: %v", err)
155		}
156		// 收款账户不存在 -> ErrNotFound，不占用请求号
157		if _, err := r.SetRoyalty(setRoyaltyReq("x4", RoyaltyShare{AccountID: "ghost", Rate: 1})); !errors.Is(err, ErrNotFound) {
158			t.Fatalf("unknown payee: %v", err)
159		}
160		if _, err := r.SetRoyalty(setRoyaltyReq("x4", RoyaltyShare{AccountID: "bob", Rate: 1})); err != nil {
161			t.Fatalf("request id x4 should not be consumed: %v", err)
162		}
163		// 收款账户已停用 -> ErrAccountInactive
164		if err := r.DeactivateAccount("dave"); err != nil {
165			t.Fatal(err)
166		}
167		if _, err := r.SetRoyalty(setRoyaltyReq("x5", RoyaltyShare{AccountID: "dave", Rate: 1})); !errors.Is(err, ErrAccountInactive) {
168			t.Fatalf("inactive payee: %v", err)
169		}
170		// 操作者（创建账户）停用 -> ErrAccountInactive
171		if err := r.DeactivateAccount("alice"); err != nil {
172			t.Fatal(err)
173		}
174		if _, err := r.SetRoyalty(setRoyaltyReq("x6", RoyaltyShare{AccountID: "bob", Rate: 1})); !errors.Is(err, ErrAccountInactive) {
175			t.Fatalf("inactive operator: %v", err)
176		}
177	}
