728		if again.Price != 1000 || again.Remainder != 500 || len(again.Payables) != 1 ||
729			again.Payables[0].Amount != 500 {
730			t.Fatalf("replayed amounts wrong: %+v (first %+v)", again, first)
731		}
732		after, _ := r.PayablesOf("carol")
733		if len(after) != len(before) {
734			t.Fatalf("replay must not double-count payables: before=%+v after=%+v", before, after)
735		}
736		// 改价 -> 请求号冲突
737		req.Price = 1001
738		if _, err := r.Transfer(req); !errors.Is(err, ErrRequestConflict) {
739			t.Fatalf("changed price must conflict, got %v", err)
740		}
741	}
742	
743	// ---- 持久化 ----
744	
745	func TestRoyaltyPersistenceAcrossReopen(t *testing.T) {
746		dir := tempDir(t)
747		r := mustCreate(t, dir)
748		royaltyWorld(t, r)
749		mustSetRoyalty(t, r, "rs1", RoyaltyShare{AccountID: "carol", Rate: 2500})
750		if _, err := r.Issue(issueReq("i1", "alice")); err != nil {
751			t.Fatal(err)
752		}
753		req := xferReq("alice", "i1", "bob", 1, "t1")
754		req.Price = 10000
755		res, err := r.Transfer(req)
756		if err != nil {
757			t.Fatal(err)
758		}
759		if err := r.Close(); err != nil {
760			t.Fatal(err)
761		}
762	
763		r2, err := Open(dir)
764		if err != nil {
765			t.Fatal(err)
766		}
767		defer r2.Close()
768		rule, _ := r2.GetSeriesRoyalty("s1")
769		if len(rule) != 1 || rule[0].AccountID != "carol" || rule[0].Rate != 2500 {
770			t.Fatalf("rule must persist: %+v", rule)
771		}
772		evs, _ := r2.RoyaltyHistory("s1")
773		if len(evs) != 1 || evs[0].RequestID != "rs1" {
774			t.Fatalf("royalty events must persist: %+v", evs)
775		}
776		ro, err := r2.TransferRoyalty(res.TxSeq)
777		if err != nil || ro.Price != 10000 || ro.Remainder != 7500 ||
778			len(ro.Payables) != 1 || ro.Payables[0].Amount != 2500 {
779			t.Fatalf("royalty record must persist: %+v %v", ro, err)
780		}
781		// 重开后原转让请求仍返回原金额
782		again, err := r2.Transfer(req)
783		if err != nil || !again.Replayed || again.Price != 10000 || again.Remainder != 7500 {
784			t.Fatalf("replayed amounts must persist: %+v %v", again, err)
785		}
786		entries, _ := r2.PayablesOf("carol")
787		if len(entries) != 1 || entries[0].Amount != 2500 {
788			t.Fatalf("payables must persist: %+v", entries)
789		}
790		// 规则已固定状态也要保留
791		if _, err := r2.SetRoyalty(setRoyaltyReq("rs2", RoyaltyShare{AccountID: "bob", Rate: 1})); !errors.Is(err, ErrRoyaltyFrozen) {
792			t.Fatalf("frozen state must persist, got %v", err)
793		}
794	}
795	
796	// ---- 旧登记册兼容 ----
797	
798	// 手写一份引入版税功能之前的旧格式快照：没有 authzs/royalties 等新字段，
799	// 含一次发行与一次转让及其请求结果。旧登记册必须能直接打开：历史保留、
800	// 旧请求可回放、旧成交按价款 0 查询且不补造应付明细。
801	func TestOpenLegacyRegistry(t *testing.T) {
802		dir := tempDir(t)
803		if err := os.MkdirAll(dir, dirMode); err != nil {
804			t.Fatal(err)
805		}
806		// 请求结果的键是 操作者 + "\x00" + 请求号；JSON 文本中以 ‌ 转义。
807		legacy := `{
808	  "version": 1,
809	  "accounts": {
810	    "alice": {"id": "alice", "metadata": "", "active": true},
811	    "bob": {"id": "bob", "metadata": "", "active": true},
812	    "carol": {"id": "carol", "metadata": "", "active": true}
813	  },
814	  "series": {
815	    "s1": {"id": "s1", "creator_id": "alice", "metadata": "", "sealed": false},
816	    "s2": {"id": "s2", "creator_id": "alice", "metadata": "", "sealed": false}
817	  },
818	  "items": {
819	    "i1": {"id": "i1", "series_id": "s1", "batch_no": "b1", "metadata": "", "issued_tx_id": 1}
820	  },
821	  "holdings": {
822	    "i1": {"item_id": "i1", "owner_id": "bob", "version": 2}
823	  },
824	  "history": [
825	    {"seq": 1, "kind": "issue", "item_id": "i1", "operator": "alice", "reason": "首发",
826	     "request_id": "req-i1", "from_id": "", "to_id": "alice", "from_version": 0, "to_version": 1},
827	    {"seq": 2, "kind": "transfer", "item_id": "i1", "operator": "alice", "reason": "卖出",
828	     "request_id": "t1", "from_id": "alice", "to_id": "bob", "from_version": 1, "to_version": 2}
829	  ],
830	  "requests": {
831	    "alice@NUL@req-i1": {"operator": "alice", "request_id": "req-i1", "kind": "issue",
832	      "params": "{\"kind\":\"issue\",\"item_id\":\"i1\",\"series_id\":\"s1\",\"batch_no\":\"b1\",\"metadata\":\"\",\"holder_id\":\"alice\",\"reason\":\"首发\"}",
833	      "rejected": false, "reject_reason": "", "item_id": "i1", "to_id": "alice", "version": 1, "tx_seq": 1},
834	    "alice@NUL@t1": {"operator": "alice", "request_id": "t1", "kind": "transfer",
835	      "params": "{\"kind\":\"transfer\",\"item_id\":\"i1\",\"expected_owner\":\"alice\",\"expected_version\":1,\"to_id\":\"bob\",\"reason\":\"卖出\"}",
836	      "rejected": false, "reject_reason": "", "item_id": "i1", "from_id": "alice", "to_id": "bob", "version": 2, "tx_seq": 2}
837	  },
838	  "next_seq": 2
839	}`
840		legacy = strings.ReplaceAll(legacy, "@NUL@", "\\u0000")
841		if err := os.WriteFile(dataFile(dir), []byte(legacy), fileMode); err != nil {
842			t.Fatal(err)
843		}
844		r, err := Open(dir)
845		if err != nil {
846			t.Fatalf("legacy registry must open: %v", err)
847		}
848		defer r.Close()
849	
850		// 旧历史保留
851		hist, err := r.History("i1")
852		if err != nil || len(hist) != 2 {
853			t.Fatalf("legacy history must be kept: %+v %v", hist, err)
854		}
855		// 旧成交按价款 0 查询，不补造应付明细
856		ro, err := r.TransferRoyalty(2)
857		if err != nil {
858			t.Fatal(err)
859		}
860		if ro.Price != 0 || ro.Remainder != 0 || len(ro.Payables) != 0 || ro.OwnerID != "alice" {
861			t.Fatalf("legacy transfer must read as zero price: %+v", ro)
862		}
863		// 旧请求仍可回放（旧签名不含价款，等价于价款 0）
864		ireq := IssueRequest{Operator: "alice", Reason: "首发", RequestID: "req-i1",
865			ItemID: "i1", SeriesID: "s1", BatchNo: "b1", HolderID: "alice"}
866		ires, err := r.Issue(ireq)
867		if err != nil || !ires.Replayed || ires.TxSeq != 1 {
868			t.Fatalf("legacy issue request must replay: %+v %v", ires, err)
869		}
870		treq := TransferRequest{Operator: "alice", Reason: "卖出", RequestID: "t1",
871			ItemID: "i1", ExpectedOwner: "alice", ExpectedVer: 1, ToID: "bob"}
872		tres, err := r.Transfer(treq)
873		if err != nil || !tres.Replayed || tres.TxSeq != 2 || tres.Price != 0 {
874			t.Fatalf("legacy transfer request must replay: %+v %v", tres, err)
875		}
876		// 旧请求改价重提 -> 请求号冲突
877		treq.Price = 5
878		if _, err := r.Transfer(treq); !errors.Is(err, ErrRequestConflict) {
879			t.Fatalf("legacy request with new price must conflict, got %v", err)
880		}
881		// 已有藏品的旧系列规则已固定；未发行的旧系列仍可设置规则
882		if _, err := r.SetRoyalty(setRoyaltyReq("n1", RoyaltyShare{AccountID: "carol", Rate: 1})); !errors.Is(err, ErrRoyaltyFrozen) {
883			t.Fatalf("legacy series with items must be frozen, got %v", err)
884		}
885		set2 := setRoyaltyReq("n2", RoyaltyShare{AccountID: "carol", Rate: 100})
886		set2.SeriesID = "s2"
887		if _, err := r.SetRoyalty(set2); err != nil {
888			t.Fatalf("legacy series without items must accept rule: %v", err)
889		}
890		// 新发行 + 新转让在旧登记册上正常记录版税（s2 规则 carol 1%）
891		ireq2 := issueReq("i2", "bob")
892		ireq2.SeriesID = "s2"
893		if _, err := r.Issue(ireq2); err != nil {
894			t.Fatal(err)
895		}
896		nreq := xferReq("bob", "i2", "carol", 1, "t2")
897		nreq.Price = 400
898		nres, err := r.Transfer(nreq)
899		if err != nil {
900			t.Fatal(err)
901		}
902		if nres.Price != 400 || len(nres.Payables) != 1 || nres.Payables[0].Amount != 4 ||
903			nres.Remainder != 396 {
904			t.Fatalf("new transfer on legacy registry wrong: %+v", nres)
905		}
906	}
